import requests
from requests.models import PreparedRequest

def test_excess_slashes():
    # We want to see if requests sends //foo to urllib3
    # Since we can't easily mock urllib3's internal ConnectionPool.urlopen without a lot of setup,
    # let's see what PreparedRequest.path_url does.

    class MockRequest(PreparedRequest):
        def __init__(self, url):
            self.url = url

    req = MockRequest("http://example.com//foo")
    path_url = req.path_url
    print(f"URL: {req.url}, path_url: {path_url}")
    assert path_url == "/foo", f"Expected /foo, got {path_url}"

if __name__ == "__main__":
    try:
        test_excess_slashes()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        exit(1)
